do $$
declare w uuid=gen_random_uuid();u uuid=gen_random_uuid();c uuid=gen_random_uuid();p shop_products;r shop_product_rewards;g uuid=gen_random_uuid();token text;slug text;payload jsonb;o jsonb;k uuid=gen_random_uuid();failed boolean;begin
 slug='pickup-'||w;
 insert into auth.users(id,email) values(u,u||'@example.invalid');
 insert into workspaces(id,salon_name,slug,owner_email,subscription_status,subscription_ends_at) values(w,'Pickup fixture',slug,u||'@example.invalid','active',now()+interval '1 year');
 insert into workspace_members(workspace_id,user_id,email) values(w,u,u||'@example.invalid');
 insert into customers(id,workspace_id,full_name,phone,email) values(c,w,'Pickup fixture','390000000001',c||'@example.invalid');
 insert into customer_login_credentials(customer_id,password_hash) values(c,extensions.crypt('fixture-only-password',extensions.gen_salt('bf')));
 token=create_customer_payment_session(slug,c||'@example.invalid','390000000001','fixture-only-password')->>'token';
 if token is null then raise exception 'Session missing';end if;
 perform set_config('request.jwt.claim.sub',u::text,true);
 perform shop_set_enabled(true,1);perform shop_store_settings(1,true,true,true,true,48);
 p=shop_create_product(gen_random_uuid(),'{"name":"Pickup shampoo","sku":"PICKUP","price_cents":2000,"cost_cents":500,"published":true,"purpose":"retail","unit":"piece","pack_size":1,"minimum_retail":0,"minimum_professional":0}');
 perform shop_adjust_stock(gen_random_uuid(),p.id,'retail','receive',2,'Carico fixture',0);
 if public_shop_catalog(slug)->'products'->0 ? 'cost_cents' then raise exception 'Cost leaked';end if;
 r=shop_save_reward(null,0,'Sconto prodotti',10,'fixed',500,null,null,false);
 insert into customer_loyalty_ledger(workspace_id,customer_id,delta,kind,reference_key,description) values(w,c,20,'service','fixture','Fixture');
 insert into customer_gift_cards(id,workspace_id,customer_id,code,amount_cents,funding) values(g,w,c,upper(substr(replace(g::text,'-',''),1,16)),1000,'complimentary');
 payload=jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('id',p.id,'quantity',2,'revision',p.revision)),'reward_id',r.id,'reward_revision',r.revision,'gift_id',g,'expected_due',2500);
 failed=false;begin perform customer_shop_order(slug,c||'@example.invalid','390000000001','bad-token',k,payload);exception when others then failed=true;end;if not failed then raise exception 'Unauthenticated order';end if;
 o=customer_shop_order(slug,c||'@example.invalid','390000000001',token,k,payload);
 perform customer_shop_order(slug,c||'@example.invalid','390000000001',token,k,payload);
 if (select reserved_qty from shop_products where id=p.id)<>2 or exists(select 1 from shop_sales where workspace_id=w) then raise exception 'Reservation charged or duplicated';end if;
 if (customer_benefits_wallet(slug,c||'@example.invalid','390000000001',token)->'giftCards'->0->>'available_cents')::bigint<>0 then raise exception 'Wallet ignores shop reserved gift credit';end if;
 if (select coalesce(sum(delta),0) from customer_loyalty_ledger where customer_id=c)<>10 then raise exception 'Points reservation wrong';end if;
 failed=false;begin perform shop_checkout(gen_random_uuid(),null,'cash',jsonb_build_array(jsonb_build_object('id',p.id,'quantity',1,'revision',p.revision)));exception when others then failed=true;end;if not failed then raise exception 'Cassa sold reserved stock';end if;
 failed=false;begin perform customer_shop_order(slug,c||'@example.invalid','390000000001',token,k,payload||'{"expected_due":1}');exception when others then failed=true;end;if not failed then raise exception 'Different retry payload accepted';end if;
 if (select count(*) from customer_benefit_notifications where workspace_id=w and event_key='shop:'||k||':pending')<>1 then raise exception 'Duplicate order notification';end if;
 p=shop_save_product(p.id,p.revision,to_jsonb(p)||'{"price_cents":3000}');
 perform shop_manage_order(k,1,'ready');perform shop_manage_order(k,2,'collected','card');perform shop_manage_order(k,2,'collected','card');
 if (select retail_qty from shop_products where id=p.id)<>0 or (select reserved_qty from shop_products where id=p.id)<>0 or (select count(*) from shop_sales where workspace_id=w)<>1 then raise exception 'Collection duplicated';end if;
 if (select total_cents from shop_sales where id=k)<>2500 or (select amount from cash_movements where id=(select cash_movement_id from shop_sales where id=k))<>25 then raise exception 'Wrong cash due';end if;
 if shop_return_quote(k,p.id,1)<>jsonb_build_object('cash_cents',1250,'gift_cents',500) then raise exception 'Incorrect refund quote';end if;
 failed=false;begin perform shop_return(gen_random_uuid(),k,p.id,1,true,'Stale quote','{"cash_cents":2000,"gift_cents":0}');exception when others then failed=true;end;if not failed then raise exception 'Stale quote accepted';end if;
 perform shop_return(gen_random_uuid(),k,p.id,1,true,'Reso parziale');
 if (select sum(amount_cents) from shop_returns where sale_id=k)<>1250 or (select sum(gift_refund_cents) from shop_returns where sale_id=k)<>500 then raise exception 'Partial refund allocation wrong';end if;
 if (select unit_price_cents from shop_sale_lines where sale_id=k and product_id=p.id)<>2000 then raise exception 'Order price snapshot changed';end if;
 perform shop_return(gen_random_uuid(),k,p.id,1,true,'Reso completo');
 if (select sum(delta) from customer_loyalty_ledger where customer_id=c)<>20 or (select state from gift_card_uses where shop_order_id=k)<>'released' then raise exception 'Full refund did not restore benefits';end if;
 payload=jsonb_set(jsonb_set(payload,'{lines,0,revision}',to_jsonb(p.revision)),'{expected_due}','4500');
 k=gen_random_uuid();o=customer_shop_order(slug,c||'@example.invalid','390000000001',token,k,payload);
 perform customer_shop_cancel(slug,c||'@example.invalid','390000000001',token,k);
 if (select reserved_qty from shop_products where id=p.id)<>0 or (select sum(delta) from customer_loyalty_ledger where customer_id=c)<>20 then raise exception 'Cancel failed to release';end if;
 payload=jsonb_set(jsonb_set(payload,'{lines,0,revision}',to_jsonb(p.revision)),'{expected_due}','4500');
 k=gen_random_uuid();o=customer_shop_order(slug,c||'@example.invalid','390000000001',token,k,payload);
 update shop_orders set expires_at=now()-interval '1 second' where id=k;perform shop_expire_orders(w);
 if (select status from shop_orders where id=k)<>'expired' or (select reserved_qty from shop_products where id=p.id)<>0 then raise exception 'Expiry failed';end if;
 perform shop_set_enabled(false,2);
 if public_shop_catalog(slug)->>'visible'<>'false' or public_shop_catalog(slug)->>'orders_supported'<>'true' then raise exception 'Disabled storefront hides existing order access';end if;
 if jsonb_array_length(customer_shop_state(slug,c||'@example.invalid','390000000001',token)->'orders')<>3 then raise exception 'Disabled shop lost history';end if;
 if has_function_privilege('anon','shop_release_order(uuid,text)','EXECUTE') or has_table_privilege('authenticated','shop_orders','UPDATE') then raise exception 'Excess privileges';end if;
end $$;
